sp_widget.client_script:
api.controller = function() {
   var c = this;

  // Open the camera on load
  navigator.mediaDevices.getUserMedia({ video: true })
    .then(function(stream) {
      document.getElementById("video").srcObject = stream;
    })
    .catch(function(err) {
      alert("Unable to access camera: " + err);
    });

  // Capture frame into canvas
  c.capture = function() {
    var video = document.getElementById("video");
    var canvas = document.getElementById("canvas");
    var context = canvas.getContext("2d");
    context.drawImage(video, 0, 0, canvas.width, canvas.height);

    // Base64 image
    var dataURL = canvas.toDataURL("image/png");
    document.getElementById("snapshot").src = dataURL;

    // store in widget state
    c.capturedData = dataURL;
  };

  // Save to server
  c.save = function() {
    if (!c.capturedData) {
      alert("Please capture an image first!");
      return;
    }

		alert('Hello 1 ' +  c.capturedData);

  c.data.myClientValue = c.capturedData; // Assign data to c.data
        c.server.update().then(function(response) {
            console.log("Server response:", response.data);
        });
  };
};

sp_widget.script:
(function() {


	try {

		 var clientValue = input.myClientValue; // Access data from input object
     gs.info("Received from client: " + clientValue);


} catch (ex) {
